const map1 = HashMap.make(["a", 1], ["b", 2], ["c", 3], ["d", 4])
const map2 = HashMap.filterMap(
  map1,
  (value) => value % 2 === 0 ? Result.succeed(value * 2) : Result.failVoid
)

map2 // => HashMap.make(["b", 4], ["d", 8])
HashMap.get(map2, "b") // => Option.some(4)

