const none = Iterable.take(numbers, 0)
Array.from(none) // => []

// Useful with infinite iterables
const naturals = Iterable.range(1)
const firstFive = Iterable.take(naturals, 5)
Array.from(firstFive) // => [1, 2, 3, 4, 5]

