const stream = Stream.make("a", "b", "c").pipe(
  Stream.intersperseAffixes({ start: "[", middle: ",", end: "]" })
)

const program = Effect.gen(function*() {
  const result = yield* Stream.runCollect(stream)
  result // => ["[", "a", ",", "b", ",", "c", "]"]
})

await Effect.runPromise(program)

