import { Effect, Layer, Stream } from "effect"
import { Chat, LanguageModel } from "effect/ai"

const FakeLanguageModel = Layer.effect(
  LanguageModel.LanguageModel,
  LanguageModel.make({
    generateText: () =>
      Effect.succeed([{
        type: "text",
