  SearchDocs: ({ query }) => Effect.succeed([query]),
  SummarizeText: ({ text }) => Effect.succeed(text)
})))

Object.keys((await Effect.runPromise(ready)).tools) // => ["SearchDocs", "SummarizeText"]

