describe "layer" with Foo.layer {
  test "adds context" {
      const foo = await Foo
      assert.strictEqual(foo, "foo")
    }

  describe "nested" with Bar.layer {
    test "adds context" {
        const foo = await Foo
        const bar = await Bar
        assert.strictEqual(foo, "foo")
        assert.strictEqual(bar, "bar")
      }
  }
}

